  lvl({"id":"rb-10","order":202,"topic":"reasoning","skill":"multi-step","band":"master","scene":"windmill","title":{"en":"Rainbow Finale","ms":"Kemuncak Pelangi"},"story":{"en":"Every colour is ready. Solve the three-step problems to finish the rainbow bridge!","ms":"Setiap warna sudah sedia. Selesaikan masalah tiga langkah untuk melengkapkan jambatan pelangi!"},"learn":{"en":"Multi-step problems with fractions, percent and money.","ms":"Masalah berbilang langkah dengan pecahan, peratus dan wang."},"critter":{"id":"arcierb","name":{"en":"Arcie","ms":"Arcie"},"blurb":{"en":"Arcie bends over every bridge in the sky.","ms":"Arcie melengkung di setiap jambatan di langit."},"look":{"body":"cloud","c1":"#a8f0e0","c2":"#3fc0a8","ears":"round","feat":"fin","acc":"none"}},"tiers":[{"id":"rb-10-a","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"One third means divide by 3.","ms":"Satu pertiga bermaksud bahagi dengan 3."},"explain":{"en":"60 ÷ 3 = 20, then 20 ÷ 2 = 10, then 10 × 3 = 30.","ms":"60 ÷ 3 = 20, kemudian 20 ÷ 2 = 10, kemudian 10 × 3 = 30."},"spec":{"steps":[{"q":{"en":"A rainbow has 60 tiles. One third are red. How many red tiles?","ms":"Sebuah pelangi mempunyai 60 jubin. Satu pertiga berwarna merah. Berapa jubin merah?"},"choices":["20","25","30","18"],"answer":0,"calc":"60/3"},{"q":{"en":"Half of the red tiles are painted twice. How many tiles is that?","ms":"Separuh daripada jubin merah dicat dua kali. Berapa jubin itu?"},"choices":["10","12","11","0"],"answer":0,"calc":"20/2"},{"q":{"en":"Each painted tile uses 3 tins. How many tins are used for them?","ms":"Setiap jubin yang dicat menggunakan 3 tin. Berapa tin digunakan untuknya?"},"choices":["31","40","30","20"],"answer":2,"calc":"10*3"}]}},{"id":"rb-10-b","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"25% is the same as one quarter.","ms":"25% sama dengan satu perempat."},"explain":{"en":"200 ÷ 4 = 50, then 50 × 6 = RM300, then 300 − 120 = RM180.","ms":"200 ÷ 4 = 50, kemudian 50 × 6 = RM300, kemudian 300 − 120 = RM180."},"spec":{"steps":[{"q":{"en":"A shop has 200 paint pots. 25% are sold. How many pots are sold?","ms":"Sebuah kedai mempunyai 200 pasu cat. 25% dijual. Berapa pasu dijual?"},"choices":["51","55","50","49"],"answer":2,"calc":"200/4"},{"q":{"en":"Each sold pot costs RM6. How much money is that?","ms":"Setiap pasu yang dijual berharga RM6. Berapa jumlah wang itu?"},"choices":["RM299","RM290","RM600","RM300"],"answer":3,"calc":"50*6"},{"q":{"en":"The shop spends RM120 on new brushes. How much money is left?","ms":"Kedai itu membelanjakan RM120 untuk berus baharu. Berapa wang yang tinggal?"},"choices":["RM180","RM90","RM190","RM182"],"answer":0,"calc":"300-120"}]}},{"id":"rb-10-c","type":"steps","prompt":{"en":"Solve each step in order.","ms":"Selesaikan setiap langkah mengikut urutan."},"hint":{"en":"Find one fifth first, then multiply by 3.","ms":"Cari satu perlima dahulu, kemudian darab dengan 3."},"explain":{"en":"40 ÷ 5 × 3 = 24, then 40 − 24 = 16, then 16 ÷ 4 = 4.","ms":"40 ÷ 5 × 3 = 24, kemudian 40 − 24 = 16, kemudian 16 ÷ 4 = 4."},"spec":{"steps":[{"q":{"en":"A bridge is 3/5 painted. The bridge has 40 planks. How many planks are painted?","ms":"Sebuah jambatan telah dicat 3/5. Jambatan itu mempunyai 40 papan. Berapa papan telah dicat?"},"choices":["25","24","14","22"],"answer":1,"calc":"40/5*3"},{"q":{"en":"How many planks are not painted yet?","ms":"Berapa papan belum dicat?"},"choices":["32","16","6","8"],"answer":1,"calc":"40-24"},{"q":{"en":"A painter paints 4 planks an hour. How many hours to finish?","ms":"Seorang pelukis mengecat 4 papan sejam. Berapa jam untuk menyiapkannya?"},"choices":["5","14","2","4"],"answer":3,"calc":"16/4"}]}}]});
